func serve(srv *http.Server) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errCh := make(chan error, 1)
	go func() {
		err := srv.ListenAndServe()
		if errors.Is(err, http.ErrServerClosed) {
			err = nil // expected after Shutdown
		}
		errCh <- err
	}()

	select {
	case err := <-errCh: // failed before any signal
		return err
	case <-ctx.Done(): // SIGINT/SIGTERM: drain
		shutCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer cancel()
		return srv.Shutdown(shutCtx)
	}
}

type Readiness struct {
	ready atomic.Bool
}

func NewReadiness() *Readiness {
	r := &Readiness{}
	r.ready.Store(true) // start ready
	return r
}

// SetReady flips the flag; call SetReady(false) on SIGTERM before draining.
func (r *Readiness) SetReady(ok bool) { r.ready.Store(ok) }

// Handler is wired to /readyz.
func (r *Readiness) Handler(w http.ResponseWriter, _ *http.Request) {
	if r.ready.Load() {
		w.WriteHeader(http.StatusOK) // 200: route traffic here
		return
	}
	w.WriteHeader(http.StatusServiceUnavailable) // 503: stop routing
}
